#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct item {
    char name[32];
    int quantity;
    double price;
};

struct inventory {
    struct item *items;
    size_t count;
    size_t capacity;
};

static int find_item(const struct inventory *inv, const char *name)
{
    for (size_t i = 0; i < inv->count; i++) {
        if (strcmp(inv->items[i].name, name) == 0) return (int)i;
    }
    return -1;
}

static int insert_item(struct inventory *inv, const char *name, int quantity, double price)
{
    if (inv->count == inv->capacity) {
        size_t new_capacity = inv->capacity == 0 ? 4 : inv->capacity * 2;
        struct item *bigger = realloc(inv->items, new_capacity * sizeof *bigger);
        if (bigger == NULL) return 0;
        inv->items = bigger;
        inv->capacity = new_capacity;
    }
    size_t at = inv->count;
    while (at > 0 && strcmp(inv->items[at - 1].name, name) > 0) {
        inv->items[at] = inv->items[at - 1];
        at--;
    }
    snprintf(inv->items[at].name, sizeof inv->items[at].name, "%s", name);
    inv->items[at].quantity = quantity;
    inv->items[at].price = price;
    inv->count++;
    return 1;
}

static void delete_item(struct inventory *inv, size_t index)
{
    for (size_t i = index + 1; i < inv->count; i++) {
        inv->items[i - 1] = inv->items[i];
    }
    inv->count--;
}

static int valid_name(const char *name)
{
    return strlen(name) <= 31;
}

static void run(struct inventory *inv, const char *line)
{
    char command[16];
    char name[64];
    int quantity = 0;
    double price = 0;
    char extra = 0;

    if (sscanf(line, "%15s", command) != 1) return;

    if (strcmp(command, "add") == 0
        && sscanf(line, "add %63s %d %lf %c", name, &quantity, &price, &extra) == 3
        && valid_name(name) && quantity >= 1 && price >= 0) {
        int at = find_item(inv, name);
        if (at >= 0) {
            inv->items[at].quantity += quantity;
            inv->items[at].price = price;
        } else if (!insert_item(inv, name, quantity, price)) {
            printf("Out of memory\n");
            return;
        }
        printf("Added %d %s\n", quantity, name);
    } else if (strcmp(command, "remove") == 0
               && sscanf(line, "remove %63s %d %c", name, &quantity, &extra) == 2
               && valid_name(name) && quantity >= 1) {
        int at = find_item(inv, name);
        if (at < 0) {
            printf("No %s\n", name);
        } else if (inv->items[at].quantity < quantity) {
            printf("Only %d %s\n", inv->items[at].quantity, name);
        } else {
            inv->items[at].quantity -= quantity;
            if (inv->items[at].quantity == 0) delete_item(inv, (size_t)at);
            printf("Removed %d %s\n", quantity, name);
        }
    } else if (strcmp(line, "list") == 0) {
        if (inv->count == 0) printf("(empty)\n");
        for (size_t i = 0; i < inv->count; i++) {
            const struct item *it = &inv->items[i];
            printf("%-16s x%-4d @ %7.2f = %8.2f\n", it->name, it->quantity, it->price, it->quantity * it->price);
        }
    } else if (strcmp(line, "total") == 0) {
        double value = 0;
        long units = 0;
        for (size_t i = 0; i < inv->count; i++) {
            value += inv->items[i].quantity * inv->items[i].price;
            units += inv->items[i].quantity;
        }
        printf("Total: %.2f (%zu items, %ld units)\n", value, inv->count, units);
    } else {
        printf("Could not read: %s\n", line);
    }
}

int main(void)
{
    struct inventory inv = {NULL, 0, 0};
    char line[256];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;
        run(&inv, line);
    }
    free(inv.items);
    return 0;
}
